using System.Globalization;
using System.Text;

namespace CFLDetectools.Core;

public sealed record PumpTestPoint(DateTimeOffset Time, string PumpId, string Scenario,
    PerformanceResult Result, RigSettings Rig, double SuctionKpa, double DischargeKpa,
    double? TorqueNm, double? SpeedRpm, double? ElectricalPowerKw);

public static class TestSessionCsv
{
    // All current sessions are generated by the simulator. Live export will require explicit provenance.
    public static string ExportSimulation(IEnumerable<PumpTestPoint> points)
    {
        var csv = new StringBuilder("time_utc,source,pump,scenario,flow_m3_h,head_m,hydraulic_kw,shaft_kw,pump_efficiency_pct,wire_to_water_pct,density_kg_m3,suction_diameter_mm,discharge_diameter_mm,elevation_difference_m,suction_kpa_g,discharge_kpa_g,torque_nm,speed_rpm,electrical_kw\r\n");
        foreach (var point in points)
        {
            string Number(double? value) => value?.ToString("G17", CultureInfo.InvariantCulture) ?? "";
            string Quote(string text) => "\"" + text.Replace("\"", "\"\"") + "\"";
            csv.AppendLine(string.Join(",", new[]
            {
                point.Time.UtcDateTime.ToString("O", CultureInfo.InvariantCulture), "Simulation",
                Quote(point.PumpId), Quote(point.Scenario), Number(point.Result.FlowM3H),
                Number(point.Result.HeadM), Number(point.Result.HydraulicPowerKw), Number(point.Result.ShaftPowerKw),
                Number(point.Result.PumpEfficiencyPercent), Number(point.Result.WireToWaterEfficiencyPercent),
                Number(point.Rig.DensityKgM3), Number(point.Rig.SuctionDiameterMm),
                Number(point.Rig.DischargeDiameterMm), Number(point.Rig.DischargeMinusSuctionElevationM),
                Number(point.SuctionKpa), Number(point.DischargeKpa), Number(point.TorqueNm),
                Number(point.SpeedRpm), Number(point.ElectricalPowerKw)
            }));
        }
        return csv.ToString();
    }
}
